public string Concatenate(string a, string b) {
    return string.Concat(a,b);
}


public string StringLeft(string str, int length) {
    if (string.IsNullOrEmpty(str)) return string.Empty;
    return str.Substring(0, Math.Min(str.Length, length));
}


public string Trim(string str) {
    return str?.Trim() ?? string.Empty;
}


public string StringConstant(string constantValue) {
    return constantValue ?? string.Empty;
}


public double Add(params double[] values) {
    double sum = 0;
    foreach(var v in values) sum += v;
    return sum;
}


public double Multiply(params double[] values) {
    if (values.Length == 0) return 0;
    double result = 1;
    foreach(var v in values) result *= v;
    return result;
}


public string If(string condition="ST",string trueValue="" ) {
    bool isTrue = !string.IsNullOrEmpty(condition) && condition.Trim().Equals("ST", StringComparison.OrdinalIgnoreCase);
    return isTrue ? trueValue : string.Empty;
}


public string AddDays(string dateStr, string daysStr) {
    if (string.IsNullOrEmpty(dateStr)) return "";
    if (!double.TryParse(daysStr ?? "0", out double days)) return dateStr;
    if (DateTime.TryParse(dateStr, out DateTime dt)) {
        dt = dt.AddDays((int)days);
        return dt.ToString("yyyy-MM-dd");
    }
    return dateStr;
}


 public static int ToAge(DateTime birthDate)
{
    DateTime today = DateTime.Today;

    // Prevent invalid future dates
    if (birthDate > today)
    {
        throw new ArgumentOutOfRangeException(nameof(birthDate), "Birthdate cannot be in the future.");
    }

    int age = today.Year - birthDate.Year;

    // Subtract a year if the birthday hasn't happened yet this year
    if (birthDate.Date > today.AddYears(-age))
    {
        age--;
    }

    return age;
}


   public string DatabaseLookup(string query,string lookupValue) {
   string connectionString=@"Server=DESKTOP-H7BVMV9\\SQLEXPRESS;Database=EDI;Integrated Security=true;TrustServerCertificate=true;";
   try {
        using (var conn = new Microsoft.Data.SqlClient.SqlConnection(connectionString))
        using (var cmd = new Microsoft.Data.SqlClient.SqlCommand(query, conn)) {
            cmd.Parameters.Add(new Microsoft.Data.SqlClient.SqlParameter("@Param", lookupValue));
            conn.Open();
            var result = cmd.ExecuteScalar();
            return result != null ? result.ToString() : string.Empty;
        }
    }
    catch (Exception ex) {
        // Gracefully return empty string on connection failures, missing columns, or bad keys
        return string.Empty;
    }
}


  public string SelectXml(string lookupValue) {
   string connectionString = @"Server=DESKTOP-H7BVMV9\SQLEXPRESS;Database=EDI;Integrated Security=true;TrustServerCertificate=true;";
   try {
        using (var conn = new Microsoft.Data.SqlClient.SqlConnection(connectionString))
        using (var cmd = new Microsoft.Data.SqlClient.SqlCommand("Select PartnerCode,PartnerName,ISA06,AddressLine1,AddressLine2,City,StateProvince,PostalCode,CountryCode from Partner where PartnerCode=@Param", conn)) {    
            cmd.Parameters.Add(new Microsoft.Data.SqlClient.SqlParameter("@Param", lookupValue));
            using (var adapter = new Microsoft.Data.SqlClient.SqlDataAdapter(cmd)) {
                 var dt = new DataTable("Rows");
                 adapter.Fill(dt);
                 using (var sw = new System.IO.StringWriter()) {
                     dt.WriteXml(sw, XmlWriteMode.IgnoreSchema);
                     string xml = sw.ToString();
                     xml = xml.Replace("<DocumentElement>", "")
                              .Replace("</DocumentElement>", "")
                              .Replace("<Rows>", "")
                              .Replace("</Rows>", "")
                              .Trim();
                     return xml;
                 }
             }
         }
    }
    catch (Exception ex) {
        // Gracefully return error message or empty string on failure
        return ex.Message;
    }
}


public string GetBillToByIsa06(string isa05, string isa06) {
